using System;
using System.Collections.Generic;

namespace GenericCollectionsDemo
{
    class Program
    {
        static void Main()
        {
            // ---- List<T> ----
            List<string> names = new List<string>
            {
                "Alice",
                "Bob",
                "Charlie"
            };
            names.Add("Diana");          // add a single element
            names.Insert(1, "Eve");      // insert at index 1

            Console.WriteLine("List<string> contents:");
            foreach (var name in names)
                Console.WriteLine($" - {name}");

            // ---- Dictionary<TKey,TValue> ----
            Dictionary<int, string> idToName = new Dictionary<int, string>();
            idToName[101] = "Alice";
            idToName[102] = "Bob";
            idToName[103] = "Charlie";

            // add with TryAdd (fails if key exists)
            bool added = idToName.TryAdd(104, "Diana");
            Console.WriteLine($"\nAdded 104: {added}");

            Console.WriteLine("\nDictionary<int,string> contents:");
            foreach (var kvp in idToName)
                Console.WriteLine($" - Id {kvp.Key}: {kvp.Value}");

            // ---- HashSet<T> ----
            HashSet<int> uniqueNumbers = new HashSet<int> { 1, 2, 3, 4, 5 };
            bool addedDuplicate = uniqueNumbers.Add(3); // will be false
            Console.WriteLine($"\nAttempt to add duplicate 3: {addedDuplicate}");

            Console.WriteLine("\nHashSet<int> contents:");
            foreach (var num in uniqueNumbers)
                Console.WriteLine($" - {num}");

            // ---- Queue<T> ----
            Queue<string> queue = new Queue<string>();
            queue.Enqueue("first");
            queue.Enqueue("second");
            queue.Enqueue("third");

            Console.WriteLine("\nQueue<string> (FIFO) contents:");
            while (queue.Count > 0)
                Console.WriteLine($" - {queue.Dequeue()}");

            // ---- Stack<T> ----
            Stack<int> stack = new Stack<int>();
            stack.Push(10);
            stack.Push(20);
            stack.Push(30);

            Console.WriteLine("\nStack<int> (LIFO) contents:");
            while (stack.Count > 0)
                Console.WriteLine($" - {stack.Pop()}");
        }
    }
}
```

**What this code shows**

| Collection | What it stores | Typical use |
|------------|----------------|-------------|
| `List<T>` | Ordered, indexable list of items | Dynamic arrays |
| `Dictionary<TKey,TValue>` | Key‑value pairs | Fast look‑ups by key |
| `HashSet<T>` | Unique items (no duplicates) | Membership tests |
| `Queue<T>` | FIFO queue | First‑in, first‑out processing |
| `Stack<T>` | LIFO stack | Last‑in, first‑out processing |

Compile and run the program; you’ll see each collection’s contents printed in order. Feel free to experiment by adding, removing, or querying elements.
